import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

let lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const used = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) used.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const x of used) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) || [])].sort(cmp)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of dl.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const k of names) if (!state.get(k)) dfs(k)

const start = new Map()
const finish = new Map()
const depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0
  let d = 0
  for (const v of dl.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
names.forEach(calc)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => (out += `wave ${i}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of dl.get(k)) rev.get(v).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const r of rev.get(u)) m = Math.max(m, pr(r))
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const fin = new Map()
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = names.length
  let t = 0
  while (remaining > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of names) {
        if (fin.has(k)) continue
        if (!dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      fin.set(best, t + cost.get(best))
      freeAt[wi] = t + cost.get(best)
      runs[wi].push(`${best}@${t}-${t + cost.get(best)}`)
      remaining--
    }
    if (remaining === 0) break
    t = Math.min(...freeAt.filter((f) => f > t), ...[...fin.values()].filter((f) => f > t))
  }
  runs.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${total}\n`
}
process.stdout.write(out)
EOF
